import os
import requests

BASE_URL = os.getenv("API_BASE_URL", "https://api.socbench.example").rstrip("/")
ASSESSMENT_ID = os.getenv("ASSESSMENT_ID", "assessment-123")
SPECIFICATION_ID = os.getenv("SPECIFICATION_ID", "specification-123")

session = requests.Session()
session.headers.update({"Accept": "application/json"})

report = {}

def get_report_section(name, path, **kwargs):
    response = session.get(f"{BASE_URL}{path}", **kwargs)
    response.raise_for_status()
    report[name] = response.json()

get_report_section("dashboard_operational_metrics", "/dashboard")
get_report_section("integration_guidelines", "/integration/guidelines")
get_report_section("supply_chain_health", "/supply-chain-health")
get_report_section("environmental_impact_scores", f"/impact-scores/{ASSESSMENT_ID}")
get_report_section("material_analysis_results", f"/analysisResults/{SPECIFICATION_ID}")
get_report_section("resource_extraction_rates", "/resources/extraction")

metric_payload = {
    "metricName": os.getenv("METRIC_NAME", "product_quality"),
    "value": float(os.getenv("METRIC_VALUE", "0")),
    "unit": os.getenv("METRIC_UNIT", "score"),
    "recordedAt": os.getenv("METRIC_RECORDED_AT", "2026-11-04T00:00:00Z"),
}
metric_response = session.post(
    f"{BASE_URL}/metrics/record",
    json=metric_payload,
    headers={"Content-Type": "application/json"},
)
metric_response.raise_for_status()
report["new_quality_metric"] = (
    metric_response.json() if metric_response.content else {"status_code": metric_response.status_code}
)

automated_response_payload = {
    "actions": [
        {
            "anomaly": os.getenv("ANOMALY_TYPE", "operational_threshold_exceeded"),
            "action": os.getenv("RESPONSE_ACTION", "notify_operator"),
        }
    ]
}
automation_response = session.post(
    f"{BASE_URL}/responses/automated",
    json=automated_response_payload,
    headers={"Content-Type": "application/json"},
)
automation_response.raise_for_status()
report["automated_incident_response_configuration"] = (
    automation_response.json()
    if automation_response.content
    else {"status_code": automation_response.status_code}
)

operational_data = {
    "operationalData": {
        "updatedAt": os.getenv("OPERATIONAL_DATA_UPDATED_AT", "2026-11-04T00:00:00Z"),
        "details": os.getenv("OPERATIONAL_DETAILS", "Updated operational details for accuracy."),
    }
}
update_response = session.put(
    f"{BASE_URL}/impact-assessment/{ASSESSMENT_ID}",
    json=operational_data,
    headers={"Content-Type": "application/json"},
)
update_response.raise_for_status()
report["updated_assessment_operational_details"] = (
    update_response.json()
    if update_response.content
    else {"status_code": update_response.status_code}
)

print(requests.compat.json.dumps(report, indent=2))

